    ('vanilla', '1.4.5.8', 'x64'): ('https://terraria.org/api/download/pc-dedicated-server/terraria-server-1458.zip', 'f513a4ac9789d34af766291ae217c9cd7d9472e13782a0e2b17512f70d7a8334'),
