def text(url):
    with urllib.request.urlopen(url, timeout=60) as response:
        return response.read(4 * 1024 * 1024).decode('utf-8')


def select_release(version):
    if version == '20.1.1':
        return {'version': version, 'prefix': 'DDNet-20.1.1-linux_x86_64',
