    if version == 'latest':
        names = re.findall(r'href="(?:https://ddnet.org/downloads/)?(DDNet-(\d+\.\d+(?:\.\d+)?)-linux_x86_64\.tar\.xz)"', text('https://ddnet.org/downloads/'))
        if not names:
