    argv, environment = configure(root, os.environ)
    credentials = [os.environ.get(key, '') for key in ('SERVER_PASSWORD', 'RCON_PASSWORD', 'STEAM_TOKEN', 'STEAM_GSLT', 'STEAM_PASS', 'STEAM_AUTH', 'SRCDS_BETAPASS')]
