#!/usr/bin/env python3
"""MIT. Native configuration and argv launch for OpenRCT2 and CS2D."""
import importlib.util
import json
import os
from pathlib import Path
import re
import queue
import secrets
import signal
import subprocess
import sys
import threading
import time
import urllib.request

