    'limbo': {'version':'2026.0.3-ALPHA-26.3-b76', 'url':'https://ci.loohpjames.com/job/Limbo/76/artifact/target/Limbo-2026.0.3-ALPHA-26.3.jar', 'sha256':'a2de91fcaa2255aed8a111b8786f370213423c7798eee778c00d016d83aa65d2'},
