        raise ValueError('Choose an exact Minecraft version and build number, or latest')
    base=('https://api.purpurmc.org/v2/purpur/' if project=='purpur' else 'https://fill.papermc.io/v3/projects/'+project+'/versions/')+version
    if project=='purpur':
