            candidates=[p for pattern in ('forge-*.jar','fabric-*.jar','quilt-*.jar') for p in ready.glob(pattern) if 'installer' not in p.name]
            if (ready/'start-server.jar').is_file():candidates=[ready/'start-server.jar']
