    "krypton/settings.gradle.kts": {
      "original_sha256": "dfc7d7ec54a3c6f9becc7f085cedbdb7de5b79ccfc82577afa73dd888161a141",
      "text": "enableFeaturePreview(\"TYPESAFE_PROJECT_ACCESSORS\")\n\ndependencyResolutionManagement {\n    repositories {\n        mavenCentral()\n        maven(\"https://repo.kryptonmc.org/releases\")\n        maven(\"https://oss.sonatype.org/content/groups/public/\")\n        maven(\"https://repo.kryptonmc.org/snapshots\")\n        maven(\"https://s01.oss.sonatype.org/content/repositories/snapshots/\")\n        maven(\"https://jitpack.io\")\n    }\n    versionCatalogs {\n        create(\"global\") {\n            from(files(\"gradle/global.versions.toml\"))\n        }\n    }\n}\n\npluginManagement {\n    includeBuild(\"build-logic\")\n    repositories {\n        maven(\"https://repo.spongepowered.org/repository/maven-public/\")\n        gradlePluginPortal()\n    }\n}\n\nplugins {\n    id(\"org.gradle.toolchains.foojay-resolver-convention\") version \"0.4.0\"\n}\n\nrootProject.name = \"krypton\"\n\ninclude(\"api\")\ninclude(\"server\")\n// Source archive contains generated API files; standalone developer generator excluded from server packaging.\ninclude(\"annotation-processor\")\ninclude(\"jar\")\n\ninternalProject(\"annotations\")\ninternalProject(\"ap\")\n\npluginProject(\"bans\")\npluginProject(\"whitelist\")\n\nfun internalProject(name: String) {\n    include(\"internal-$name\")\n    project(\":internal-$name\").projectDir = file(\"internal/$name\")\n}\n\nfun pluginProject(name: String) {\n    include(\"$name-plugin\")\n    project(\":$name-plugin\").projectDir = file(\"plugins/$name\")\n}\n\n// BEGIN VOLTRA PINNED PUBLISHER SOURCE COMPOSITE\nincludeBuild(\"../nbt-src\") {\n    dependencySubstitution {\n        substitute(module(\"org.kryptonmc:nbt-common\")).using(project(\":common\"))\n        substitute(module(\"org.kryptonmc:nbt-extra-kotlin\")).using(project(\":extra-kotlin\"))\n    }\n}\nincludeBuild(\"../serialization-src\") {\n    dependencySubstitution {\n        substitute(module(\"org.kryptonmc:serialization-core\")).using(project(\":serialization-core\"))\n        substitute(module(\"org.kryptonmc:serialization-gson\")).using(project(\":serialization-gson\"))\n        substitute(module(\"org.kryptonmc:serialization-nbt\")).using(project(\":serialization-nbt\"))\n    }\n}\nincludeBuild(\"../brigadier-src\") {\n    dependencySubstitution {\n        substitute(module(\"org.kryptonmc:krypton-brigadier\")).using(project(\":\"))\n    }\n}\nincludeBuild(\"../DataConverter-src\") {\n    dependencySubstitution {\n        substitute(module(\"ca.spottedleaf:dataconverter\")).using(project(\":\"))\n    }\n}\n"
    },
    "krypton/server/build.gradle.kts": {
      "original_sha256": "b277dc9c494eb2f8a6bbd69a97dd7a6013f469225017e67308decdc67227832b",
      "text": "import org.apache.tools.ant.filters.ReplaceTokens\n\nplugins {\n    id(\"krypton.api-conventions\")\n    id(\"io.gitlab.arturbosch.detekt\")\n    id(\"com.google.devtools.ksp\")\n    jacoco\n}\n\ndependencies {\n    api(projects.api)\n    implementation(projects.annotationProcessor)\n\n    // Logging and console\n    runtimeOnly(libs.log4j.core)\n    implementation(libs.tca)\n    runtimeOnly(libs.jline.jansi)\n\n    // Data\n    api(libs.dataConverter)\n    api(libs.nbt)\n    api(libs.nbt.kotlin)\n    api(libs.serialization)\n    api(libs.serialization.gson)\n    api(libs.serialization.nbt)\n    implementation(files(rootProject.file(\"../articdata-data.jar\"))) // Explicit same-Minecraft publisher-data restoration; original artifact unavailable.\n\n    // Collections and caching\n    implementation(libs.fastutil)\n    implementation(libs.flare.fastutil)\n    implementation(libs.caffeine)\n    implementation(libs.jctools)\n\n    // Miscellaneous\n    implementation(libs.clikt)\n    implementation(libs.bstats)\n    implementation(libs.kotlinx.collections.immutable)\n    compileOnly(projects.internalAnnotations)\n    ksp(projects.internalAp)\n    implementation(libs.reflections)\n    implementation(libs.hydrazine)\n\n    testImplementation(libs.junit.api)\n    testImplementation(libs.junit.engine)\n    testImplementation(libs.kotlin.test.junit)\n    testImplementation(libs.junit.platform.runner)\n    testImplementation(libs.mockk)\n    testImplementation(libs.jimfs)\n    testRuntimeOnly(libs.bytebuddy)\n    testImplementation(projects.internalAnnotations)\n    testImplementation(libs.equalsVerifier)\n    testImplementation(libs.jsonassert)\n}\n\nlicense {\n    exclude(\n        \"**/*.properties\",\n        \"**/*.conf\",\n        \"**/*.json\",\n        // Velocity derivatives, with a special header\n        \"**/plugin/KryptonPluginManager.kt\",\n        \"**/plugin/PluginClassLoader.kt\",\n        \"**/plugin/PluginDependencies.kt\",\n        // Sponge derivatives, with a special header\n        \"**/console/BrigadierCompleter.kt\",\n        \"**/console/BrigadierHighlighter.kt\"\n    )\n}\n\ntasks {\n    withType<ProcessResources> {\n        filesMatching(\"**/versions.properties\") {\n            val minecraftVersion = global.versions.minecraft.get()\n            filter<ReplaceTokens>(\"tokens\" to mapOf(\n                \"krypton\" to project.version.toString(),\n                \"minecraft\" to minecraftVersion,\n                \"data\" to minecraftVersion.replace('.', '_')\n            ))\n        }\n    }\n    jacocoTestReport {\n        dependsOn(test)\n        reports {\n            html.required.set(true)\n            xml.required.set(true)\n        }\n    }\n    build {\n        dependsOn(test)\n    }\n    compileKotlin {\n        compilerOptions.freeCompilerArgs.add(\"-Xjvm-default=all\")\n    }\n    withType<Test> {\n        useJUnitPlatform()\n    }\n}\n\nsetupDetekt()\n"
    },
