    "brigadier-src/build.gradle": {
      "original_sha256": "6a3ce5fe0928476d1b1684c487c959e4e4c3d89303c6280ef92f7b449e0a288b",
      "text": "apply plugin: 'java-library'\napply plugin: 'maven-publish'\n\ngroup = 'org.kryptonmc'\nversion = project.hasProperty('buildNumber') ? \"${project.majorMinor}.${project.buildNumber}\" : \"${project.majorMinor}.0-SNAPSHOT\"\n\nbuildscript {\n    repositories {\n        mavenCentral()\n        maven {\n            url \"https://libraries.minecraft.net\"\n        }\n    }\n}\n\nrepositories {\n    maven {\n        url \"https://libraries.minecraft.net\"\n    }\n    mavenCentral()\n}\n\ndependencies {\n    testImplementation 'com.google.guava:guava:26.0-jre'\n    testImplementation 'junit:junit-dep:4.11'\n    testImplementation 'org.hamcrest:hamcrest-library:1.3'\n    testImplementation 'org.mockito:mockito-core:1.10.19'\n    testImplementation 'com.google.guava:guava-testlib:26.0-jre'\n    testImplementation 'org.openjdk.jmh:jmh-core:1.21'\n    annotationProcessor 'org.openjdk.jmh:jmh-generator-annprocess:1.21'\n}\n\ntask sourcesJar(type: Jar) {\n    archiveClassifier.set('sources')\n    from sourceSets.main.allSource\n}\n\nsourceSets {\n    main {\n        java {\n            srcDirs = ['src/main/java']\n        }\n        resources {\n            srcDirs = ['src/main/resources']\n        }\n    }\n    test {\n        java {\n            srcDirs = ['src/test/java']\n        }\n        resources {\n            srcDirs = ['src/test/resources']\n        }\n    }\n}\n\nartifacts {\n    archives jar\n    archives sourcesJar\n}\n\ntest {\n    testLogging {\n        events \"failed\", \"skipped\"\n        showStandardStreams = true\n        showExceptions true\n    }\n}\n\npublishing {\n    publications {\n        mavenJava(MavenPublication) {\n            from components.java\n            artifact sourcesJar\n        }\n    }\n}\n\ntask report {\n    doLast {\n        println \"##teamcity[buildNumber '${project.version}']\"\n    }\n}\n\npublishing {\n    repositories {\n        maven {\n            credentials {\n                username System.getenv(\"NEXUS_USERNAME\")\n                password System.getenv(\"NEXUS_PASSWORD\")\n            }\n\n            name = 'krypton'\n            def base = 'https://repo.kryptonmc.org'\n            def releasesRepoUrl = \"$base/releases\"\n            def snapshotsRepoUrl = \"$base/snapshots\"\n            url = version.endsWith('SNAPSHOT') ? snapshotsRepoUrl : releasesRepoUrl\n        }\n    }\n}"
    },
