      "text": "metadata.format.version = \"1.1\"\n\n[versions]\n# Module dependency versions\nannotations = \"23.0.0\"\ngson = \"2.9.1\"\nguava = \"31.1-jre\"\nnbt = \"4.3.2\"\n\n# Plugin dependency versions\ncontractValidator = \"1.0.1\"\nerrorprone = \"2.14.0\"\nstylecheck = \"0.1\"\ncheckstyle = \"9.3\"\n\n# Plugin versions\nerrorpronePlugin = \"3.1.0\"\nindra = \"2.1.1\"\nlicenser = \"0.6.1\"\n\n[libraries]\n# Module dependencies\nannotations = { group = \"org.jetbrains\", name = \"annotations\", version.ref = \"annotations\" }\ngson = { group = \"com.google.code.gson\", name = \"gson\", version.ref = \"gson\" }\nguava = { group = \"com.google.guava\", name = \"guava\", version.ref = \"guava\" }\nnbt = { group = \"org.kryptonmc\", name = \"nbt-common\", version.ref = \"nbt\" }\n\n# Plugin dependencies\ncontractValidator = { group = \"ca.stellardrift\", name = \"contract-validator\", version.ref = \"contractValidator\" }\nerrorprone = { group = \"com.google.errorprone\", name = \"error_prone_core\", version.ref = \"errorprone\" }\nstylecheck = { group = \"ca.stellardrift\", name = \"stylecheck\", version.ref = \"stylecheck\" }\n\n# Plugins\nplugin-errorprone = { group = \"net.ltgt.gradle\", name = \"gradle-errorprone-plugin\", version.ref = \"errorpronePlugin\" }\nplugin-indra = { group = \"net.kyori\", name = \"indra-common\", version.ref = \"indra\" }\nplugin-licenser = { group = \"gradle.plugin.org.cadixdev.gradle\", name = \"licenser\", version.ref = \"licenser\" }\n"
