    jar=env.get('SERVER_JARFILE','Limbo.jar' if kind=='limbo' else 'server.jar')
    if not re.fullmatch(r'[A-Za-z0-9_][A-Za-z0-9_.-]{0,120}\.jar',jar):raise ValueError('Choose a jar filename within this volume')
