        else:
            namespace='net/neoforged/'+('forge' if version=='1.20.1' else 'neoforge');artifact=namespace.rsplit('/',1)[1]
            if not explicit:
                raw=fetch('https://maven.neoforged.net/releases/'+namespace+'/maven-metadata.xml')
