            try:
                child=subprocess.Popen([sys.executable,'-c',BOOTSTRAP,str(reader),str(Path(__file__).parent)],cwd=root,
                    env=dict(os.environ),stdin=subprocess.PIPE,stdout=None,stderr=None,pass_fds=(reader,),start_new_session=True)
