    sm_pin=PINNED.get('sm-'+str(sm),{})
    if '/'+series+'/' not in sm_pin.get('url',''):sm_pin={}
    records=[dict(PINNED.get('mms-'+str(mms),{'url':f'https://mms.alliedmods.net/mmsdrop/1.11/mmsource-1.11.0-git{mms}-linux.tar.gz'})),
