RECIPES = {'cs2': (730, 'game/csgo', 'game/bin/linuxsteamrt64/cs2'),
           'sven': (276060, 'svencoop', 'svends_run'),
           'tf2classic': (244310, 'tf2classic', 'srcds_run')}
HOSTS = ('wiki.tf2classic.com', 'wiki.tf2classified.com')


def selection(env):
