 'mms-1148': {'url':'https://mms.alliedmods.net/mmsdrop/1.11/mmsource-1.11.0-git1148-linux.tar.gz','bytes':1859973,'sha256':'977607008ec94dd5fff6e5bc351fcf1610e2e9852ac61268fc798a6a1d282a2d'},
