    argv+=(['-log','MaxSlots='+mapping['MaxSlots']] if windows else ['-MaxSlots='+mapping['MaxSlots']])
    argv+=['-USEALLAVAILABLECORES','-Port='+str(ports['primary']),'-QueryPort='+str(ports['QUERY_PORT']),'-Beaconport='+str(ports['BEACON_PORT'])]
