            for line in sys.stdin:
                if done.is_set():
                    return
                if plan['rcon_enabled']:
                    try:
                        reply = common.command(plan['ports']['RCON_PORT'], plan['rcon_password'], line.rstrip('\r\n'))
                        emit((reply + '\n').encode(), redactor)
                    except (OSError, ValueError, EOFError):
