        key, separator, value = item.partition('=')
        if not separator or not re.fullmatch('[A-Za-z][A-Za-z0-9_]*', key) or key.lower() in result:
            raise ValueError('Malformed or duplicate ARK URL parameter')
        url_value(value)
        result[key.lower()] = (key, value)
