    result = {'SERVER_PORT': primary}
    for key in ('QUERY_PORT', 'RCON_PORT'):
        enabled = key == 'QUERY_PORT' or game == 'conan' or boolean(env, 'SHUTDOWN_SERVICE' if game == 'empires' else 'RCON_ENABLED', game == 'empires')
