                os.killpg(child.pid, signal.SIGKILL);child.wait()
        for pid in native_pids(root, plan['binary']) if game != 'enhanced' else []:
            try:
                os.kill(pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
