                '-CULTUREFORCOOKING=en', '-NoBattlEye', '-QueryPort=' + str(listeners['QueryPort']),
                '-Port=' + str(listeners['Port']), '-CubePort=' + str(listeners['CubePort']),
                '-cubeworld=' + name, '-nosteamclient', '-NoHangDetection']
    elif game == 'ascended':
