        properties.setdefault(key, default)
    properties.update(disableThirdPerson=boolean(env, 'DISABLE_THIRD'), fastValidation=True,
                      battlEye=boolean(env, 'BATTLEYE', True))
    for role, name in [('A2S_PORT', 'a2s'), ('RCON_PORT', 'rcon')]:
