"""MIT. Shared SteamCMD contract for imported game templates, without shell flags."""
import hashlib
from contextlib import contextmanager
import json
import os
from pathlib import Path, PurePosixPath
import re
import secrets
import shutil
import subprocess
import stat
import tarfile
import tempfile
