    if game != 'pixark':
        if primary + 1 not in available:
            raise ValueError('ARK requires primary-plus-one peer allocation')
        used.add(primary + 1)

    def take(key, role, optional=False, query_pair=False):
        value = env.get(key, '')
        if optional and value in ('', '0'):
            return
        if value:
            value = integer(env, key, 0)
        else:
