def citadel_path(root, relative):
    for alias in ('Citadel/Saved/Config/LinuxServer', 'Engine/Saved/Config/LinuxServer'):
        link = root / alias
        if (relative == alias or relative.startswith(alias + '/')) and link.is_symlink():
