    def emit(data):
        if not filtered or (b'LogCore: Warning' not in data and b'LogUObjectBase: Error' not in data):
            sys.stdout.buffer.write(redactor.feed(data, final=data.endswith(b'\n')))
            sys.stdout.buffer.flush()
