    if not re.fullmatch(pattern + '(?:,' + pattern + ')*', raw):
        raise ValueError('Mod IDs must be ordered comma-separated numeric IDs' + (' with optional -dev suffix' if dev else ''))
    return ','.join(dict.fromkeys(raw.split(',')))


