    selected={key:env.get(key,'') for key in ('STEAM_USER','STEAM_PASS','STEAM_AUTH','SRCDS_BETAID','SRCDS_BETAPASS','INSTALL_FLAGS')}
    steam.arguments(root,app,selected,platform=platform,force_platform=True)
