    result = []
    if isinstance(value, dict):
        for key, item in value.items():
            if re.search(r'password|secret|token|authkey|^pin$|adminpin', key, re.I) and isinstance(item, (str, int)) and not isinstance(item, bool):
                result.append(str(item))
